"""tally: counts the words, lines, or characters of a file."""
import sys


def count(text, how):
    if how == "--lines":
        return len(text.splitlines())
    if how == "--chars":
        return len(text)
    return len(text.split())


def main(argv):
    how = argv[1] if argv[1].startswith("--") else ""
    name = argv[-1]
    with open(name, encoding="utf-8") as f:
        print(count(f.read(), how), name)


if __name__ == "__main__":
    main(sys.argv)
